public final class MemberCheck { public static void main(String[] args) { Host left=new Host("K"), right=new Host("other"); if (!left.decorate("O").equals("OK")) throw new AssertionError("dispatch state"); if (left.same(right) || left.result(right) || !left.same(left)) throw new AssertionError("distinct receiver objects"); if (left.sizeOrZero(null)!=0 || left.sizeOrZero("abc")!=3) throw new AssertionError("nullable extension"); Parent child=new Child(); if (!child.run("x").equals("childx")) throw new AssertionError("virtual dispatch"); if (!MemberConsumerKt.consume(left).equals("OK") || MemberConsumerKt.distinct(left,right) || MemberConsumerKt.nullable(left)!=0) throw new AssertionError("metadata consumer"); } }
